#include <vector>
#include <unordered_map>

class Solution {
public:
    int validKUniqueSubarraysWithMinSum(std::vector<int>& nums, int k, int min_sum) {
        int n = nums.size();
        int ans = 0;
        for (int r = 0; r < n; ++r) {
            std::unordered_map<int, int> f;
            int s = 0;
            for (int l = r; l >= 0; --l) {
                f[nums[l]]++;
                if ((int)f.size() > k) break;
                s += nums[l];
                if (s >= min_sum) ans++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int validKUniqueSubarraysWithMinSum(int[] nums, int k, int minSum) {
        int n = nums.length;
        int ans = 0;
        for (int r = 0; r < n; r++) {
            Map<Integer, Integer> f = new HashMap<>();
            int s = 0;
            for (int l = r; l >= 0; l--) {
                f.put(nums[l], f.getOrDefault(nums[l], 0) + 1);
                if (f.size() > k) break;
                s += nums[l];
                if (s >= minSum) ans++;
            }
        }
        return ans;
    }
}

